    && (await shown(page.getByTestId('bulk-retired'))) !== '' && ((await shown(page.getByTestId('bulk-retired'))) !== was || was === ''),
    page.getByTestId('person-error'), 'bulk retire');
  return ok ? Number(await shown(page.getByTestId('bulk-retired'))) : null;
